const a={title:"TripReel - Besplatna Aplikacija za Animaciju Putovanja: Pretvorite Fotografije u Lijepa Videa",description:"Stvorite zadivljujuće videozapise putovanja s animiranim kartama i rutama leta. Besplatna aplikacija za animaciju putovanja s 3D mapiranjem ruta globusa. Automatski pretvorite svoje fotografije u lijepa putna videa. Privatnost na prvom mjestu, radi offline.",keywords:"aplikacija za animaciju putovanja, aplikacija za animaciju karte putovanja, aplikacija za animaciju rute putovanja, aplikacija za animaciju leta, kreator videozapisa putovanja, automatski video putovanja, animirana karta putovanja, animacija rute leta, animacija putovanja, animacija globusa, video rekapitulacije putovanja, fotografija u video, istaknuti dijelovi putovanja, besplatna aplikacija za putovanja, kreator videozapisa offline, privatna aplikacija za putovanja, video kamere"},i={logoAlt:"TripReel Logo",appName:"TripReel",howItWorks:"Kako Funkcionira",video:"Video",features:"Značajke",theApp:"Aplikacija"},e={badge:"Pretvorite Fotografije u Putopisne Priče",title1:"Vaša Galerija,",title2:"U Potpunosti Iskorištena",description:"TripReel automatski stvara prekrasne putopisne videozapise iz lokacija vaših fotografija. Gledajte kako vaša putovanja oživljavaju s animiranim kartama ruta i letačkim putanjama na 3D globusu, dok vaši podaci ostaju privatni i sigurni.",secure:"100% Sigurno",worksOffline:"Radi Offline",globeAlt:"TripReel Animacija Globusa"},o={title:"Kako Funkcionira",subtitle:"Tri jednostavna koraka do savršenog putopisnog videozapisa",step1:{title:"Dopustite Pristup Fotografijama",description:"Omogućite TripReelu pristup vašoj foto-biblioteci. Aplikacija čita samo metapodatke o lokaciji, ništa drugo."},step2:{title:"Automatsko Prepoznavanje Putovanja",description:"TripReel analizira metapodatke o lokaciji i inteligentno pronalazi vaša putovanja na temelju datuma i lokacija."},step3:{title:"Generirajte Svoj Videozapis",description:"Gledajte kako se vaše putovanje odvija na prekrasnoj animaciji globusa, spremno za dijeljenje na društvenim mrežama."}},t={title:"Vidite Čaroliju u Akciji",subtitle:"Pogledajte kako TripReel pretvara vašu foto-biblioteku u nevjerojatne putopisne videozapise",caption:"Ovako može izgledati vaš konačni putopisni videozapis"},n={title:"Sve Što Vam Treba",subtitle:"Moćne značajke dizajnirane za moderne putnike",twoTap:{title:"Video u Dva Dodira",description:"Stvorite zadivljujuće putopisne videozapise iz svoje foto-biblioteke u samo dva dodira. Bez uređivanja."},smartTrip:{title:"Pametno Prepoznavanje Putovanja",description:"Automatski pronalazi i grupira vaša putovanja analizirajući datume i metapodatke o lokaciji iz fotografija."},globe:{title:"Prekrasna Animacija Globusa",description:"Gledajte kako vaše putovanje oživljava sa zadivljujućim 3D globusom koji prikazuje animirane rute putovanja i letačke putanje diljem svijeta."},privacy:{title:"Privatnost na Prvom Mjestu",description:"Sve se obrađuje na vašem uređaju. Vaše fotografije nikada ne napuštaju vaš telefon. Radi u zrakoplovnom načinu rada."},customStyles:{title:"Prilagodljivi Stilovi",description:"Odaberite između više stilova globusa i prilagodbi kako biste odgovarali svojoj estetici i učinili svaki video jedinstvenim."},manualControl:{title:"Ručna Kontrola",description:"Možete ručno dodati potpuno nova putovanja ako usluge lokacije nisu bile omogućene na vašem uređaju."}},r={title:"Kreativne Ideje za Videozapise",subtitle:"Inspirirajte se onim što možete stvoriti koristeći TripReel. Od kratkih vikend-izleta do jednogodišnjih avantura, stvorite zadivljujuće putopisne videozapise za svako putovanje.",description:"Bilo da stvarate animaciju putne karte, dokumentirate letačku rutu ili pravite godišnju rekapitulaciju putovanja, TripReel olakšava pretvaranje vaših uspomena u videozapise koje možete podijeliti.",ideas:{yearRecap:{title:"Rekapitulacija 2025.",description:"Automatski stvorite videozapis godišnje rekapitulacije putovanja za 2025."},europeRoadTrip:{title:"Europski Road Trip",description:"Prikažite svoju europsku avanturu s animiranim kartama ruta"},southeastAsia:{title:"Putovanje Jugoistočnom Azijom",description:"Vizualizirajte svoju rutu kroz više zemalja"},japanRail:{title:"Putovanje Vlakom kroz Japan",description:"Stvorite video-zapise svojih željezničkih ruta kroz Japan"},crossCountry:{title:"Putovanje kroz SAD",description:"Pretvorite svoje američko putovanje u epski video rute"},islandHopping:{title:"Skakanje po Otocima",description:"Pokažite svoja putovanja s otoka na otok uz zadivljujuće 3D animacije"},worldTour:{title:"Svjetska Turneja",description:"Više putovanja u jedan nevjerojatan globalni video"},travelPlans:{title:"Putni Planovi za 2026.",description:"Vizualizirajte i planirajte svoje uzbudljive putničke avanture za 2026."},lifetimeTravel:{title:"Životna Putopisna Priča",description:"Stvorite videozapis koji prikazuje sva vaša putovanja kroz život"},regionalExplorer:{title:"Regionalni Istraživač",description:"Zabilježite svoje avanture kroz države, pokrajine i regije"},festivalCircuit:{title:"Festival Circuit",description:"Mapirajte svoje putovanje kroz glazbene festivale i događaje"},bikeRoutes:{title:"Moji Gradski Izleti",description:"Prikažite sve svoje gradske eskapade"}}},u={title:"Aplikacija",subtitle:"Sada dostupno na App Storeu",alt1:"Automatski Putopisni Videozapisi - Stvorite zadivljujuće videozapise u sekundama",alt2:"Detekcija Lokacije Fotografija - Koristi metapodatke vaših fotografija",alt3:"Detekcija Putovanja - Automatski grupira vaša putovanja",alt4:"Prekrasni Videozapisi Globusa - Animacija globusa vašeg putovanja",alt5:"Prilagođeni Stilovi - Personalizirajte svoje putopisne videozapise"},s={comingSoon:"Uskoro",androidTitle:"Android Aplikacija Uskoro!",androidMessage:'Android verzija još nije dostupna, ali će biti uskoro. Pošaljite mi poruku na <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> i javit ću vam kada bude spremna!',gotIt:"Razumijem!"},p={title:"Često Postavljana Pitanja",subtitle:"Sve što trebate znati o TripReelu",q1:{question:"Mogu li stvarno koristiti aplikaciju u potpunosti u zrakoplovnom načinu rada?",answer:"Da! Za premium korisnike, aplikacija se može koristiti potpuno offline u zrakoplovnom načinu rada bez ograničenja. Za ne-premium korisnike, neke značajke podržavaju oglasi koji bi mogli zahtijevati privremeno omogućavanje interneta, ali za premium korisnike nema oglasa i aplikacija se može potpuno koristiti u zrakoplovnom načinu rada."},q2:{question:"Nadogradio sam na Premium, kako mogu ukloniti vodeni žig?",answer:"Mnogi ljudi pitaju koja je aplikacija korištena za stvaranje ovih videozapisa, stoga, nakon nadogradnje na premium, imate mogućnost dodati manju verziju vodenog žiga (samo s imenom aplikacije) ili ga potpuno ukloniti ako želite."},q3:{question:"Jesu li moji foto-podaci sigurni i privatni?",answer:"Apsolutno! TripReel čita samo metapodatke o lokaciji iz vaših fotografija - nikada ne pristupamo, ne pohranjujemo niti prenosimo stvarni sadržaj fotografija. Sva obrada odvija se lokalno na vašem uređaju, i nijedan podatak nikada ne napušta vaš telefon. To možete provjeriti koristeći aplikaciju u zrakoplovnom načinu rada - savršeno radi offline!"},q4:{question:"Što ako moje fotografije nemaju podatke o lokaciji?",answer:"Nema problema! Ako usluge lokacije nisu bile omogućene kada ste fotografirali, možete ručno stvoriti putovanja i sami dodati lokacije. Aplikacija vam daje punu kontrolu za prilagodbu vremenske crte putovanja."},q5:{question:"Kako aplikacija automatski prepoznaje moja putovanja?",answer:"TripReel analizira metapodatke o lokaciji i vremenske oznake iz vaših fotografija kako bi inteligentno identificirao kada i gdje ste putovali. Grupira obližnje lokacije i datume kako bi automatski prepoznao vaša putovanja bez ikakve ručne intervencije."},q6:{question:"Mogu li prilagoditi izgled svojih videozapisa?",answer:"Da! Možete birati između više stilova globusa i prilagoditi razne aspekte svojih animiranih putopisnih videozapisa kako bi odgovarali vašoj osobnoj estetici. Premium korisnici imaju pristup dodatnim stilovima animacije ruta, temama karti i opcijama letačkih putanja."},q7:{question:"Trebam li stvoriti račun?",answer:"Račun nije potreban! TripReel radi odmah nakon preuzimanja. Nema registracije, nema prijave i nisu potrebne osobne informacije. Samo preuzmite aplikaciju i odmah počnite stvarati svoje putopisne videozapise."},q8:{question:"Zašto nedostaje lokacija iz mog putovanja?",answer:"Aplikacija može raditi samo s dostupnim podacima, stoga prvo morate imati barem nekoliko fotografija na toj lokaciji. Drugo, morate se uvjeriti da ste imali omogućene podatke o lokaciji dok ste bili tamo. Treće, ponekad slab GPS prijem može uzrokovati pogrešne podatke o lokaciji. Ako ste isključili sve ovo, a vaša lokacija se još uvijek ne prikazuje, možete ručno dodati tu lokaciju iz Trips Overview > gumb Edit. Molimo također koristite Contact za prijavljivanje problema."},q9:{question:"Gdje mogu podijeliti svoj videozapis?",answer:"Naravno, možete ga podijeliti i na svim društvenim platformama. Kako bi bolje odgovarao platformi, aplikacija omogućava različite omjere slike za vaše videozapise."},q10:{question:"Gdje mogu prijaviti grešku?",answer:"Samo me izravno kontaktirajte na marian@qod.ee, ukratko objašnjavajući u čemu je problem."}},j={title:"Podrška putem E-maila",description:"Ako imate bilo kakvih povratnih informacija ili naiđete na bilo kakve probleme, slobodno me izravno kontaktirajte na ovaj e-mail i osobno ću pročitati i obraditi vaš zahtjev što je brže moguće. Hvala što koristite aplikaciju!",close:"Zatvori"},l={default:{title:"🍪 Kolačići",message:"Koristimo kolačiće na TripReel stranici kako bismo poboljšali vaše iskustvo. Ne prikupljamo osobne podatke.",accept:"Prihvati",decline:"Odbij",details:"Detalji"},theme:{title:"🍪 Kolačići",message:"🌙 Kako biste spremili svoju postavku teme, trebate prihvatiti osnovne kolačiće na TripReel stranici. Bez njih, vaš izbor teme ne može biti spremljen.",accept:"Prihvati",decline:"Odbij",details:"Detalji"}},v={privacy:"Pravila Privatnosti Aplikacije",cookies:"Pravila o Kolačićima Stranice",contact:"Kontakt",cookiePreferences:"Postavke Kolačića",madeWith:"Napravljeno s",forTravelers:"za putnike diljem svijeta",copyright:"© {{year}} TripReel."},k={title:"Spremni Podijeliti Svoje Putovanje?",description:"Preuzmite TripReel danas i pretvorite svoju galeriju u prekrasne putopisne videozapise s animiranim kartama i rutama. Vaše avanture zaslužuju biti proslavljena.",features:"Besplatno preuzimanje • Brzo i Praktično • Privatnost zajamčena"},m={title:"O aplikaciji TripReel",subtitle:"Profesionalni kreator video isječaka putovanja i aplikacija za animaciju ruta",howItWorks:{title:"Kako funkcionira naša aplikacija za sažetak putovanja",description:"Aplikacija za animaciju putovanja koristi inteligentne algoritme za skeniranje GPS podataka vaših fotografija i automatsko otkrivanje vaših putovanja. Animator ruta putovanja zatim stvara glatke, kinematografske animacije ruta putovanja koje prikazuju vaš put kroz gradove, zemlje i kontinente. Bilo da stvarate brzi video isječak vikend putovanja ili godišnji sažetak putovanja, aplikacija za animiranu kartu putovanja to čini jednostavnim."},customization:{title:"Opsežna prilagodba za vaše video animacije putovanja",description:"Aplikacija za kreiranje priča o putovanjima nudi opcije prilagodbe profesionalne razine kako bi vaši videozapisi s animiranim kartama putovanja bili zaista jedinstveni:",features:{videoQuality:"Odaberite između 30 FPS, 60 FPS ili premium 90 FPS za svilenkasto glatke animacije ruta putovanja u vašim video isječcima putovanja",bitrate:"Prilagodite kvalitetu videa (bitrate) od normalne do visoke za kristalno čiste videozapise s kartama putovanja bez vizualnih artefakata",earthStyles:"Odaberite između više zapanjujućih stilova Zemlje uključujući Realistični, Noćna svjetla, Dnevna karta i satelitske prikaze za vaše videozapise s animiranim kartama putovanja",borders:"Prebacite granice država na svom animatoru ruta putovanja s prilagodljivim bojama i debljinom za poboljšanu vizualizaciju geografije",aspectRatios:"Stvorite videozapise s animacijom putovanja u formatima Okomito (9:16), Široki ekran (16:9), Kino (2.35:1) ili Kvadrat (1:1) savršenim za Instagram, TikTok, YouTube i druge društvene platforme",tripSpeed:"Kontrolirajte brzinu animatora ruta putovanja između lokacija (do 3500 km/s) kako biste stvorili dinamične ili opuštene videozapise sa sažetkom putovanja",pauseDuration:"Prilagodite trajanje pauze na svakoj lokaciji (0,5-5 sekundi) kako biste istaknuli važne destinacije u vašim video isječcima putovanja",locationLabels:"Prikažite oznake Grad, Regija i/ili Država na vašim videozapisima s animiranim kartama putovanja kako biste pružili kontekst za vaše putovanje",pathDisplay:"Prebacite želite li prikazati sve prošle rute putovanja ili samo trenutno putovanje u vašoj animaciji rute putovanja"}}},d={meta:a,header:i,hero:e,howItWorks:o,videoSection:t,features:n,videoIdeas:r,screenshots:u,appStore:s,faq:p,contact:j,cookieBanner:l,footer:v,cta:k,about:m};export{m as about,s as appStore,j as contact,l as cookieBanner,k as cta,d as default,p as faq,n as features,v as footer,i as header,e as hero,o as howItWorks,a as meta,u as screenshots,r as videoIdeas,t as videoSection};
